+impl Analyzer {
+    fn qv(&self, id: QubitId) -> Val {
+        if id == NO_QUBIT { Unknown } else { self.q[id.0 as usize] }
+    }
+    fn bv(&self, id: BitId) -> Val {
+        if id == NO_BIT { Unknown } else { self.b[id.0 as usize] }
+    }
+    fn set_q(&mut self, id: QubitId, v: Val) {
+        self.q[id.0 as usize] = v;
