+/// XOR of two abstract values when both known.
+fn xor_val(a: Val, b: Val) -> Val {
+    match (a, b) {
+        (Zero, x) | (x, Zero) => x,
+        (One, One) => Zero,
+        _ => Unknown,
+    }
+}
+
+/// AND of two abstract values.
+fn and_val(a: Val, b: Val) -> Val {
+    match (a, b) {
+        (Zero, _) | (_, Zero) => Zero,
+        (One, One) => One,
+        _ => Unknown,
+    }
+}
